// Block (composition) — a contact form paired with a contact-information section.
// Grid/Stack own arrangement; Form/TextField/Textarea/Button own form behavior and Component look.
import { useId, type FormEvent, type ReactNode, type Ref } from "react";
import { Button } from "../components/Button";
import { Form } from "../components/Form";
import { Grid } from "../layouts/Grid";
import { Stack } from "../layouts/Stack";
import { Textarea } from "../components/Textarea";
import { TextField } from "../components/TextField";
import "./ContactSplit.css";

export interface ContactSplitProps {
  onSubmit?: (data: Record<string, string>) => void;
  isPending?: boolean;
  info?: {
    label: string;
    value: ReactNode;
  }[];
  heading?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function ContactSplit({
  onSubmit,
  isPending,
  info = [],
  heading = "Get in touch",
  className,
  ref,
}: ContactSplitProps) {
  const headingId = useId();

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    onSubmit?.({
      name: String(data.get("name") ?? ""),
      email: String(data.get("email") ?? ""),
      message: String(data.get("message") ?? ""),
    });
  };

  return (
    <Grid
      as="section"
      ref={ref}
      aria-labelledby={headingId}
      columns={{ small: 1, medium: 2 }}
      gap={{ small: "2x-large", medium: "large" }}
      className={className ? `sd-contactsplit ${className}` : "sd-contactsplit"}
    >
      {/* The heading names the whole section, so it comes first in reading order, above the form on a
          phone and beside it from the medium step. */}
      <Stack gap="large" className="sd-contactsplit__info">
        <>
          <h2 id={headingId} className="sd-contactsplit__heading sd-type-title-medium">{heading}</h2>
        </>
        {info.length > 0 && (
          <Stack as="dl" gap="medium" className="sd-contactsplit__list">
            {info.map((item, index) => (
              <div key={`${item.label}-${index}`} className="sd-contactsplit__item">
                <dt className="sd-contactsplit__label sd-type-label-medium">{item.label}</dt>
                <dd className="sd-contactsplit__value sd-type-body-medium">{item.value}</dd>
              </div>
            ))}
          </Stack>
        )}
      </Stack>

      <Form isPending={isPending} onSubmit={handleSubmit} className="sd-contactsplit__form">
        {/* `medium`: three labelled fields stacked, the field-field row. Each field's label sits
            `x-small` above its control, and parting fields takes two rungs over that, as the other
            full forms already do (token-contract.md § By relationship). */}
        <Stack gap="medium" className="sd-contactsplit__fields">
          <TextField label="Name" name="name" autoComplete="name" isRequired />
          <TextField
            label="Email"
            name="email"
            type="email"
            autoComplete="email"
            isRequired
          />
          <Textarea label="Message" name="message" rows={6} isRequired />
          <Button size="large" type="submit" variant="primary" isPending={isPending}>
            Send
          </Button>
        </Stack>
      </Form>
    </Grid>
  );
}

.sd-contactsplit {
  width: 100%;
}

.sd-contactsplit__form,
.sd-contactsplit__info {
  min-width: 0;
}

.sd-contactsplit__heading,
.sd-contactsplit__list,
.sd-contactsplit__label,
.sd-contactsplit__value {
  margin: 0;
}

.sd-contactsplit__item {
  display: grid;
  gap: var(--sd-space-2x-small);
}
